SELECT p.id AS position_id, p.symbol, COUNT(m.id) AS events, MIN(m.price) AS min_price, MAX(m.price) AS max_price, MIN(m.observed_at) AS first_obs, MAX(m.observed_at) AS last_obs FROM crypto_ai.paper_position p LEFT JOIN crypto_ai.market_price_event m ON m.symbol = p.symbol AND m.observed_at BETWEEN p.opened_at AND p.closed_at WHERE p.id IN (182,172,162,158,143,137) GROUP BY p.id, p.symbol LIMIT 6